        foreach($suffix in $Networks.Keys){$owned=$Networks[$suffix];$n=(Must (Native 'docker' @('network','inspect',$owned.id)) | ConvertFrom-Json)[0];if($n.Id -ne $owned.id -or $n.Name -ne $owned.name -or $n.Labels.'neshane.xref.run' -ne $RunId -or @($n.Containers.PSObject.Properties).Count){throw 'Cleanup network ID/name/label/nonempty mismatch'};[void](Must (Native 'docker' @('network','rm',$owned.id)))}
