        foreach($kind in @('container','network','volume')){[string[]]$remainingOwned=@();if($kind -eq 'container'){$remainingOwned=@(& docker ps -aq --filter "label=neshane.xref.run=$RunId")}else{$remainingOwned=@(& docker $kind ls -q --filter "label=neshane.xref.run=$RunId")};if($LASTEXITCODE -ne 0 -or $remainingOwned.Length -ne 0){throw "Independent $kind absence check failed"}}
        Save 'cleanup.json' @{status='PASS';containers=$Containers;networks=$Networks;volumes=$Volumes;privateScratchRemoved=(-not(Test-Path $Scratch));protectedResources='UNCHANGED';independentResourceAbsence=$true}
        if($Code -eq 0 -and -not $PrerequisitesOnly -and -not $IntegrationDiagnostic -and (Test-Path (Join-Path $Evidence 'full-driver.json'))){Save 'x40-cleanup.json' @{id='X40/cleanup';actual='CLEAN';status='OBSERVED';run=$RunId;cleanup='cleanup.json';interpretation='Automatic and independent absence checks completed; verifier required'};[IO.File]::AppendAllText((Join-Path $Evidence 'variant-index.jsonl'),((@{id='X40/cleanup';path='x40-cleanup.json'} | ConvertTo-Json -Compress)+"`n"),$Utf8)}
    }catch{$Code=2;Save 'cleanup-failure.json' @{status='FAIL';reason=$_.Exception.Message};Write-Output ('Cleanup failure: '+$_.Exception.Message)}
